components.css:
.ds-practice-review{background:#fff;color:#161616;font:14px/1.5 "Segoe UI","Microsoft YaHei",sans-serif;}.ds-practice-review *{box-sizing:border-box;}.ds-practice-review button{cursor:pointer;}.ds-practice-review button:focus-visible{outline:2px solid #161616;outline-offset:4px;}.ds-practice-review { margin: 20px 0 24px; padding: 16px 0; border-block: 1px solid #161616; scroll-margin-block: 24px; }
.ds-practice-review-heading { display: flex; align-items: baseline; justify-content: space-between; flex-wrap: wrap; gap: 8px 16px; }
.ds-practice-review-heading h3 { margin: 0; font-size: 17px; font-weight: 600; line-height: 1.5; }
.ds-practice-review-heading > span { font-size: 17px; font-weight: 600; font-variant-numeric: tabular-nums; }
.ds-practice-review-summary { margin: 8px 0 16px; max-width: 65ch; font-size: 14px; line-height: 1.7; color: #161616; }
.ds-practice-review-keys { display: flex; flex-wrap: wrap; gap: 4px; }
.ds-practice-review-keys button { display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 4px; min-width: 44px; min-height: 52px; padding: 6px 10px; border: 1px solid #d6d6d6; background: #fff; color: #161616; font-size: 14px; font-variant-numeric: tabular-nums; }
.ds-practice-review-keys button[data-correct="false"] { background: #161616; border-color: #161616; color: #fff; }
.ds-practice-review-keys button:disabled { opacity: .5; }
.ds-practice-review-keys button[aria-current="step"] { outline: 2px solid #161616; outline-offset: 2px; }
.ds-practice-review-guide { display: flex; flex-wrap: wrap; align-items: center; gap: 8px 16px; margin-top: 12px; font-size: 12px; color: #595959; }
.ds-practice-review-guide > span { display: inline-flex; align-items: center; gap: 4px; }
.ds-practice-review-guide .piano-text-button { font-size: 13px; }
.ds-practice-review-note { margin-top: 12px; font-size: 12px; line-height: 1.7; color: #595959; }
.ds-practice-review-note p { margin: 0; }
@media (hover: hover) and (pointer: fine) { .ds-practice-review-keys button:not(:disabled):hover { border-color: #161616; text-decoration: underline; text-underline-offset: 3px; } }
